// Builds api/_pricebook.js from the Brenicks price book exported as JSON ({items:[{id, offer, price:{T1..T5}, unit}]}).
// Run after any price change:  node api/_pricebook-build.mjs pricebook.json
// The checkout (api/checkout.js) reads only the generated file, so the price book stays the one place a price is set.
import { readFileSync, writeFileSync } from 'node:fs';

const src = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const book = src.data || src;
const TIERS = ['T1', 'T2', 'T3', 'T4', 'T5'];
const cents = (s) => Math.round(Number(String(s).replace(/[^\d.]/g, '')) * 100);
function parse(raw) {
  const s = String(raw).replace(/\/.*$/, '').trim();               // "$300/mo" -> "$300"
  const m = s.match(/^\$([\d,.]+)\s*-\s*([\d,.]+)(\+?)$/);         // "$10,000-30,000" or "$30,000-150,000+"
  if (m) return { min: cents(m[1]), max: m[3] ? null : cents(m[2]) };
  if (!/^\$[\d,.]+$/.test(s)) throw new Error('Cannot read price "' + raw + '"');
  return { amount: cents(s) };
}
const LINKS = { // today's public payment links (T1), used only while the checkout has no Stripe key
  'PB-001': 'https://buy.stripe.com/test_28EbJ19Frglefrw77P0480b', 'PB-002': 'https://buy.stripe.com/test_aFa8wP2cZ1qk2EK0Jr0480c',
  'PB-003': 'https://buy.stripe.com/test_5kQcN59Frgle0wCfEl0480d', 'PB-004': 'https://buy.stripe.com/test_5kQ8wPg3P6KEfrwcs90480e',
  'PB-005': 'https://buy.stripe.com/test_4gMeVdeZL6KE938bo50480f', 'PB-006': 'https://buy.stripe.com/test_aFa00j6tf6KE938cs90480g',
  'PB-007': 'https://buy.stripe.com/test_00waEX2cZed6frwak10480i', 'PB-008': 'https://buy.stripe.com/test_bJefZh5pb3ysdjo2Rz0480k',
  'PB-009': 'https://buy.stripe.com/test_28EfZh3h38SM93877P0480l', 'PB-010': 'https://buy.stripe.com/test_eVqaEXeZLc4Ybbgak104800',
  'PB-011': 'https://buy.stripe.com/test_4gMcN5cRD3ysa7c8bT04801', 'PB-013': 'https://buy.stripe.com/test_6oU28reZL4Cwa7cak104802',
  'PB-014': 'https://buy.stripe.com/test_9B600jeZLfha7Z4ak10480m', 'PB-015': 'https://buy.stripe.com/test_28E9AT6tfglegvA0Jr0480n',
  'PB-016': 'https://buy.stripe.com/test_5kQcN56tf8SM3IO2Rz0480o',
};
const PAGES = { web: '/web-design/', salesforce: '/salesforce/', ai: '/ai-implementation/' };
const out = {};
for (const it of book.items || []) {
  const [svc, ...rest] = String(it.offer).split(': ');
  const service = /^web/i.test(svc) ? 'web' : /^sales/i.test(svc) ? 'salesforce' : 'ai';
  const unit = String(it.unit || 'one-off');
  const name = rest.join(': ').replace(/\s*\((min \d+ users|fixed once scoped|scoped)\)\s*$/i, '');
  const minUsers = Number((String(it.offer).match(/min (\d+) users/i) || [])[1] || 0);
  const price = {}; for (const t of TIERS) price[t] = parse(it.price[t]);
  out[it.id] = { name, service, page: PAGES[service], per_user: /user/.test(unit), monthly: /mo$/.test(unit), min_qty: minUsers || 1, price, link: LINKS[it.id] || '' };
}
const rules = book.rules || {};
const MARKETS = { US: 'T1' }; const ISO = { 'South Africa': 'ZA', Ireland: 'IE', Mexico: 'MX', Spain: 'ES' };
for (const m of rules.launch_markets || []) { const x = String(m).match(/^(.*?)\s*\((T\d)\)$/); if (x && ISO[x[1]]) MARKETS[ISO[x[1]]] = x[2]; }
const body = `// GENERATED by api/_pricebook-build.mjs from the price book (updated ${book.updated || 'unknown'}). Do not edit by hand.
// Amounts are US cents. A price with min/max is quoted per client (signed link carries the amount); max null means open-ended.
export const UPDATED = ${JSON.stringify(book.updated || '')};
export const TIERS = ${JSON.stringify(TIERS)};
// Markets open for tiered prices: country (ISO code) -> tier. T1 is open to every country (size and headquarters rules).
export const MARKETS = ${JSON.stringify(MARKETS)};
export const PACKAGES = {
${Object.entries(out).map(([k, v]) => '  ' + JSON.stringify(k) + ': ' + JSON.stringify(v)).join(',\n')},
};
`;
writeFileSync(new URL('./_pricebook.js', import.meta.url), body);
console.log('Wrote api/_pricebook.js:', Object.keys(out).length, 'packages x', TIERS.length, 'tiers; markets', JSON.stringify(MARKETS));
